# ENGR 311 (Transform Calculus & PDEs, Dr. Su, Fall 2026) — theory/recall bank. Zill AEM: Ch 4, Ch 12, Ch 13 (13.1–13.6).
# Tags follow STYLE.md against the provided formula sheet (midterm version; assume the final's sheet is the same plus any Ch 13 additions):
#   p.1 = transform table, derivative transforms, translation theorems (incl. alternative form), U(t−a), tⁿf(t), ∫f, periodic f, δ, linearity, integration by parts
#   p.2 = convolution integral + theorem, orthogonality w.r.t. w(x), norm, full Fourier series on (−p,p) with a0, an, bn, trig and hyperbolic identities
# NOT on the sheet: existence conditions, half-range (cosine/sine) coefficient formulas, convergence theorem, PDE forms, separation of variables, classification.
C = "engr311"
S4, S12, S13, PS = "Ch 4 slides – The Laplace Transform", "Ch 12 slides – Orthogonal Functions & Fourier Series", "Ch 13 slides – Boundary-Value Problems", "Midterm 2 procedures sheet"
P1, P2, DEF = "(sheet p.1)", "(sheet p.2)", "(definition, not on the sheet)"
Q = []
def add(kind, id, topic, q, exp, src, **kw):
    d = dict(id=f"e311-{id}", course=C, topic=topic, type=kind, question=q, explanation=exp, source=src); d.update(kw); Q.append(d)
def mcq(id, topic, q, choices, ans, exp, src): add("mcq", id, topic, q, exp, src, choices=choices, answer=ans)
def tf(id, topic, q, ans, exp, src): add("tf", id, topic, q, exp, src, answer=ans)
def sa(id, topic, q, ans, exp, src, kw=()): add("short", id, topic, q, exp, src, answer=ans, keywords=list(kw))

T = "Laplace basics"
mcq("lt-01", T, "The Laplace transform of $f(t)$ is defined as:", ["$\\int_0^\\infty e^{-st}f(t)\\,dt$", "$\\int_{-\\infty}^\\infty e^{-st}f(t)\\,dt$", "$\\int_0^\\infty e^{st}f(t)\\,dt$", "$\\int_0^t e^{-s\\tau}f(\\tau)\\,d\\tau$"], 0, "$\\mathcal L\\{f\\}=\\int_0^\\infty e^{-st}f(t)\\,dt$ " + P1 + "\nIt's an improper integral, so it converges only for $s$ large enough.", S4)
sa("lt-02", T, "State sufficient conditions for $\\mathcal L\\{f(t)\\}$ to exist for $s>c$.", "$f$ is piecewise continuous on $[0,\\infty)$ and of exponential order $c$: $|f(t)|\\le Me^{ct}$ for $t>T$.", "Existence theorem " + DEF + "\nThese are sufficient, not necessary: $t^{-1/2}$ has a transform anyway.", S4, ["piecewise continuous", "exponential order"])
tf("lt-03", T, "$f(t)=e^{t^2}$ has a Laplace transform.", False, "It grows faster than any $Me^{ct}$, so it isn't of exponential order " + DEF + ".\nThe integral diverges for every $s$.", S4)
mcq("lt-04", T, "$\\mathcal L\\{t^n\\}$ for $n=0,1,2,\\dots$ is:", ["$\\dfrac{n!}{s^{n+1}}$", "$\\dfrac{n!}{s^n}$", "$\\dfrac{1}{s^{n+1}}$", "$\\dfrac{(n+1)!}{s^{n+1}}$"], 0, "Table row $t^n$ " + P1 + "\nCheck: $n=0$ gives $1/s$; $n=1$ gives $1/s^2$.", S4)
mcq("lt-05", T, "$\\mathcal L\\{\\sin kt\\}$ is:", ["$\\dfrac{k}{s^2+k^2}$", "$\\dfrac{s}{s^2+k^2}$", "$\\dfrac{k}{s^2-k^2}$", "$\\dfrac{1}{s^2+k^2}$"], 0, "Table " + P1 + ":\n$\\sin kt\\to k/(s^2+k^2)$\n$\\cos kt\\to s/(s^2+k^2)$\nsinh and cosh have $s^2-k^2$ instead.", S4)
mcq("lt-06", T, "$\\mathcal L\\{e^{at}\\}$ is:", ["$\\dfrac{1}{s-a}$, for $s>a$", "$\\dfrac{1}{s+a}$", "$\\dfrac{a}{s-a}$", "$\\dfrac{s}{s-a}$"], 0, "Table " + P1 + "\nFrom the definition: integrate $e^{-(s-a)t}$ from 0 to ∞, which converges only when $s>a$.", S4)
tf("lt-07", T, "The Laplace transform is linear: $\\mathcal L\\{\\alpha f+\\beta g\\}=\\alpha F(s)+\\beta G(s)$.", True, "Linearity property " + P1 + "\nThe inverse is linear too, which is why partial fractions work.", S4)
tf("lt-08", T, "$\\mathcal L\\{f(t)g(t)\\}=F(s)G(s)$.", False, "The transform of a product is NOT the product of the transforms.\n$F(s)G(s)=\\mathcal L\\{f*g\\}$ (convolution theorem " + P2 + ").", S4)
tf("lt-09", T, "If $f$ is piecewise continuous and of exponential order, then $F(s)\\to0$ as $s\\to\\infty$.", True, "Behaviour as $s\\to\\infty$ " + DEF + "\nSo $F(s)=s/(s+1)$ can't be the transform of such an $f$.", S4)

T = "Transforms of derivatives & IVPs"
mcq("dv-01", T, "$\\mathcal L\\{y''(t)\\}$ equals:", ["$s^2Y(s)-sy(0)-y'(0)$", "$s^2Y(s)-y(0)-sy'(0)$", "$s^2Y(s)+sy(0)+y'(0)$", "$sY(s)-y(0)$"], 0, "Derivative rows " + P1 + ":\n$\\mathcal L\\{f'\\}=sF-f(0)$\n$\\mathcal L\\{f''\\}=s^2F-sf(0)-f'(0)$\nThe powers of $s$ go down while the derivative order of the initial values goes up.", S4)
sa("dv-02", T, "Outline the steps for solving a linear constant-coefficient IVP with the Laplace transform.", "1) Transform both sides, inserting the initial conditions through the derivative rows. 2) Solve the algebraic equation for $Y(s)$. 3) Use partial fractions and the theorems to invert: $y=\\mathcal L^{-1}\\{Y\\}$.", "Derivative rows " + P1 + "\nThe initial conditions go in at step 1, so there are no constants to fit at the end.", S4, ["transform", "solve for Y(s)", "inverse transform"])
tf("dv-03", T, "The Laplace method builds the initial conditions in automatically, so no constants need to be fitted at the end.", True, "That's its main advantage over undetermined coefficients for IVPs.", S4)
mcq("dv-04", T, "$\\mathcal L\\left\\{\\int_0^t f(\\tau)\\,d\\tau\\right\\}$ equals:", ["$F(s)/s$", "$sF(s)$", "$F(s)-f(0)$", "$F'(s)$"], 0, "Integral row " + P1 + "\nIt's also the convolution theorem " + P2 + " with $g=1$, $G=1/s$.", S4)

T = "Translation theorems"
mcq("tr-01", T, "First translation theorem: $\\mathcal L\\{e^{at}f(t)\\}=$", ["$F(s-a)$", "$F(s+a)$", "$e^{-as}F(s)$", "$e^{as}F(s)$"], 0, "Row $e^{at}f(t)\\to F(s-a)$ " + P1 + "\nMultiplying by an exponential in $t$ shifts along the $s$-axis.", S4)
mcq("tr-02", T, "$\\mathcal L\\{e^{-2t}\\cos3t\\}$ is:", ["$\\dfrac{s+2}{(s+2)^2+9}$", "$\\dfrac{s-2}{(s-2)^2+9}$", "$\\dfrac{s}{(s+2)^2+9}$", "$\\dfrac{3}{(s+2)^2+9}$"], 0, "$\\mathcal L\\{\\cos3t\\}=\\dfrac{s}{s^2+9}$ " + P1 + "\nHere $a=-2$, so replace $s$ with $s-(-2)=s+2$ everywhere " + P1 + ".", S4)
mcq("tr-03", T, "The unit step function $\\mathcal U(t-a)$ equals:", ["0 for $0\\le t<a$, 1 for $t\\ge a$", "1 for $t<a$, 0 for $t\\ge a$", "1 only at $t=a$", "$t-a$ for $t\\ge a$"], 0, "Definition " + DEF + "\n$\\mathcal L\\{\\mathcal U(t-a)\\}=e^{-as}/s$ " + P1, S4)
mcq("tr-04", T, "Second translation theorem: $\\mathcal L\\{f(t-a)\\mathcal U(t-a)\\}=$", ["$e^{-as}F(s)$", "$F(s-a)$", "$e^{as}F(s)$", "$F(s)/s$"], 0, "Row " + P1 + "\nA delay of $a$ in time multiplies the transform by $e^{-as}$. The minus sign comes from shifting right.", S4)
mcq("tr-05", T, "The alternative form gives $\\mathcal L\\{g(t)\\mathcal U(t-a)\\}=$", ["$e^{-as}\\mathcal L\\{g(t+a)\\}$", "$e^{-as}\\mathcal L\\{g(t)\\}$", "$\\mathcal L\\{g(t-a)\\}$", "$e^{as}\\mathcal L\\{g(t+a)\\}$"], 0, "Row " + P1 + "\nUse it when $g$ isn't already written as a shifted function, e.g. $t^2\\,\\mathcal U(t-1)$: $g(t+1)=(t+1)^2$.", S4)
sa("tr-06", T, "Write $f(t)=\\begin{cases}2 & 0\\le t<3\\\\ -1 & t\\ge3\\end{cases}$ with unit steps.", "$f(t)=2-3\\,\\mathcal U(t-3)$", "Start with the first piece.\nAt each break add (new − old)·$\\mathcal U(t-a)$: here $(-1-2)\\,\\mathcal U(t-3)$.", S4, ["2 − 3U(t−3)"])
mcq("tr-07", T, "$\\mathcal L^{-1}\\left\\{\\dfrac{e^{-2s}}{s^2}\\right\\}$ is:", ["$(t-2)\\,\\mathcal U(t-2)$", "$t\\,\\mathcal U(t-2)$", "$e^{-2t}t$", "$(t+2)\\,\\mathcal U(t-2)$"], 0, "$\\mathcal L^{-1}\\{1/s^2\\}=t$ " + P1 + "\nThe factor $e^{-2s}$ means shift by 2 and switch on at $t=2$ " + P1 + ".", S4)
tf("tr-08", T, "To invert $\\dfrac{1}{s^2+4s+13}$, complete the square to $(s+2)^2+9$ and use the first translation theorem.", True, "$\\dfrac{1}{(s+2)^2+9}=\\dfrac13\\cdot\\dfrac{3}{(s+2)^2+9}$\n$\\mathcal L^{-1}=\\tfrac13e^{-2t}\\sin3t$ (rows $\\sin kt$ and $e^{at}f$ " + P1 + ")", S4)

T = "Operational properties"
mcq("op-01", T, "$\\mathcal L\\{t\\,f(t)\\}$ equals:", ["$-\\dfrac{d}{ds}F(s)$", "$\\dfrac{d}{ds}F(s)$", "$sF(s)$", "$F(s)/s$"], 0, "Row $t^nf(t)\\to(-1)^n\\dfrac{d^nF}{ds^n}$ " + P1 + "\nWith $n=1$ the sign is negative.", S4)
mcq("op-02", T, "The convolution $f*g$ is:", ["$\\int_0^t f(\\tau)g(t-\\tau)\\,d\\tau$", "$\\int_0^\\infty f(\\tau)g(\\tau)\\,d\\tau$", "$f(t)g(t)$", "$\\int_0^t f(\\tau)g(\\tau)\\,d\\tau$"], 0, "Convolution integral " + P2 + "\nConvolution theorem: $\\mathcal L\\{f*g\\}=F(s)G(s)$ " + P2, S4)
tf("op-03", T, "Convolution is commutative: $f*g=g*f$.", True, "Substitute $u=t-\\tau$ in the integral " + P2 + ".", S4)
sa("op-04", T, "What kind of equation is $f(t)=g(t)+\\int_0^t f(\\tau)h(t-\\tau)d\\tau$, and how does Laplace solve it?", "A Volterra integral equation. The integral is $f*h$, so transforming gives $F=G+FH$, hence $F=\\dfrac{G}{1-H}$. Then invert.", "Convolution theorem " + P2 + "\nThe same method handles integro-differential equations such as LRC circuits.", S4, ["Volterra", "convolution", "F = G/(1−H)"])
mcq("op-05", T, "If $f$ is periodic with period $T$, then $\\mathcal L\\{f\\}=$", ["$\\dfrac{1}{1-e^{-sT}}\\int_0^T e^{-st}f(t)\\,dt$", "$\\int_0^T e^{-st}f(t)\\,dt$", "$\\dfrac{1}{1+e^{-sT}}\\int_0^T e^{-st}f(t)\\,dt$", "$T\\int_0^T e^{-st}f(t)\\,dt$"], 0, "Periodic row " + P1 + "\nYou only integrate over one period.", S4)

T = "Dirac delta & systems"
mcq("dd-01", T, "$\\mathcal L\\{\\delta(t-t_0)\\}$ for $t_0>0$ is:", ["$e^{-st_0}$", "$1/s$", "$e^{-st_0}/s$", "1"], 0, "δ row " + P1 + "\nWith $t_0=0$: $\\mathcal L\\{\\delta(t)\\}=1$.", S4)
tf("dd-02", T, "The Dirac delta is an ordinary function equal to ∞ at $t_0$ and 0 elsewhere.", False, "It's a generalized function, defined as a limit of unit impulses or by its sifting property $\\int f(t)\\delta(t-t_0)dt=f(t_0)$ " + DEF + ".", S4)
sa("dd-03", T, "What physical situation does $\\delta(t-t_0)$ model on the right side of a spring–mass equation?", "A sudden impulse at $t=t_0$ (a large force acting for a very short time, e.g. a hammer blow) with total impulse 1.", "The velocity jumps at $t_0$ while the displacement stays continuous.", S4, ["impulse", "short time", "hammer blow"])
tf("dd-04", T, "Laplace turns a system of linear constant-coefficient ODEs into algebraic equations in $X(s)$, $Y(s)$.", True, "Transform each equation with the derivative rows " + P1 + ".\nSolve by elimination or Cramer's rule, then invert each one.", S4)

T = "Orthogonal functions"
mcq("of-01", T, "Functions $f_1$, $f_2$ are orthogonal on $[a,b]$ if:", ["$\\int_a^b f_1f_2\\,dx=0$", "$f_1(x)f_2(x)=0$ for all $x$", "$\\int_a^b (f_1+f_2)\\,dx=0$", "$f_1'=f_2$"], 0, "Orthogonal sets " + P2 + " with weight $w(x)=1$.", S12)
tf("of-02", T, "$x^2$ and $x^3$ are orthogonal on $[-1,1]$.", True, "$\\int_{-1}^1x^2\\cdot x^3dx=\\int_{-1}^1x^5dx=0$\n$x^5$ is odd and the interval is symmetric.", S12)
mcq("of-03", T, "The norm of $\\phi_n$ on $[a,b]$ is:", ["$\\|\\phi_n\\|=\\sqrt{\\int_a^b\\phi_n^2\\,dx}$", "$\\int_a^b\\phi_n\\,dx$", "$\\int_a^b\\phi_n^2\\,dx$", "$\\max|\\phi_n|$"], 0, "Norm " + P2 + "\n$\\|\\phi_n\\|^2$ is the square norm. A set with every norm equal to 1 is orthonormal.", S12)
mcq("of-04", T, "On $[-\\pi,\\pi]$, $\\|\\cos nx\\|$ for $n\\ge1$ equals:", ["$\\sqrt\\pi$", "$\\pi$", "$\\sqrt{2\\pi}$", "1"], 0, "Norm " + P2 + ": $\\|\\cos nx\\|^2=\\int_{-\\pi}^{\\pi}\\cos^2nx\\,dx$\nUse $\\cos^2\\theta=\\tfrac12(1+\\cos2\\theta)$ (rearranged from the $\\cos2\\theta$ identity " + P2 + ")\n$=\\pi$, so $\\|\\cos nx\\|=\\sqrt\\pi$.\n$\\phi_0=1$ is the exception: its norm is $\\sqrt{2\\pi}$.", S12)
mcq("of-05", T, "In an orthogonal series $f=\\sum c_n\\phi_n$, the coefficients are:", ["$c_n=\\dfrac{(f,\\phi_n)}{\\|\\phi_n\\|^2}$", "$c_n=(f,\\phi_n)$", "$c_n=\\|\\phi_n\\|^2$", "$c_n=f(n)$"], 0, "(derived) Multiply both sides by $\\phi_m$ and integrate.\nOrthogonality " + P2 + " kills every term except $n=m$.\n$(f,\\phi_m)=c_m\\|\\phi_m\\|^2$", S12)
tf("of-06", T, "$\\{\\phi_n\\}$ is orthogonal with respect to $w(x)$ if $\\int_a^b w\\,\\phi_m\\phi_n\\,dx=0$ for $m\\ne n$.", True, "Orthogonal sets " + P2 + "\nWeight functions appear in Sturm–Liouville problems.", S12)
sa("of-07", T, "What's the classic trap in $\\int\\cos mx\\cos nx\\,dx$ with product-to-sum formulas?", "Dividing by $m-n$ when $m=n$. Do the $m=n$ case (the norm) separately, and handle special members like $\\phi_0=1$ separately too.", "Product-to-sum identities " + P2 + "\nThis trap is called out on the Midterm 2 procedures sheet.", PS, ["m = n separately", "don't divide by m−n", "φ0 special"])

T = "Fourier series"
mcq("fs-01", T, "In the Fourier series of $f$ on $(-p,p)$, $a_n$ is:", ["$\\dfrac1p\\int_{-p}^pf(x)\\cos\\dfrac{n\\pi x}{p}dx$", "$\\dfrac{1}{2p}\\int_{-p}^pf(x)\\cos\\dfrac{n\\pi x}{p}dx$", "$\\dfrac2p\\int_{-p}^pf(x)\\cos\\dfrac{n\\pi x}{p}dx$", "$\\int_{-p}^pf(x)\\cos(nx)dx$"], 0, "Fourier series row " + P2 + "\n$a_0=\\frac1p\\int_{-p}^pf\\,dx$, and the series starts with $a_0/2$.", S12)
tf("fs-02", T, "The series begins with $a_0/2$ so that the same formula for $a_n$ also works at $n=0$.", True, "Fourier series row " + P2 + "\nSo the constant term is the average value of $f$ over the interval.", S12)
mcq("fs-03", T, "At a jump $x=c$, the Fourier series of a piecewise-smooth $f$ converges to:", ["$\\dfrac{f(c^+)+f(c^-)}{2}$", "$f(c^+)$", "$f(c^-)$", "0"], 0, "Convergence theorem " + DEF + "\nWhere $f$ is continuous, the series converges to $f(c)$.", S12)
mcq("fs-04", T, "At the endpoint $x=p$, the full Fourier series converges to:", ["$\\dfrac{f(-p^+)+f(p^-)}{2}$", "$f(p)$", "0", "$f(0)$"], 0, "The periodic extension joins the right end of the interval to the left end.\nConvergence theorem " + DEF, PS)
mcq("fs-05", T, "If $f$ is even on $(-p,p)$, its Fourier series contains:", ["Only $a_0$ and cosines ($b_n=0$)", "Only sines", "Both", "Only $a_0$"], 0, "(derived) $f\\sin(n\\pi x/p)$ is even × odd = odd, so $b_n=0$ " + P2 + ".\n$f\\cos$ is even, so $a_n=\\frac2p\\int_0^pf\\cos\\frac{n\\pi x}p dx$.", S12)
mcq("fs-06", T, "The product of two odd functions is:", ["Even", "Odd", "Neither", "Zero"], 0, "Parity rules " + DEF + ":\neven × even = even\nodd × odd = even\neven × odd = odd", S12)
tf("fs-07", T, "If $f$ is odd, then $\\int_{-a}^af(x)dx=0$.", True, "The areas left and right of zero cancel.\nFor even $f$: $\\int_{-a}^af=2\\int_0^af$.", S12)
mcq("fs-08", T, "Which function is neither even nor odd?", ["$x+x^2$", "$|x|$", "$x^3$", "$\\cos x$"], 0, "Its even part ($x^2$) feeds $a_n$; its odd part ($x$) feeds $b_n$.", PS)
mcq("fs-09", T, "The Gibbs phenomenon is:", ["An overshoot of about 9% near a jump that narrows but never shrinks as terms are added", "Divergence at a jump", "Slow convergence of smooth functions", "Convergence to the wrong function"], 0, "Gibbs " + DEF + "\nThe overshoot stays even as $N\\to\\infty$; it just moves closer to the jump.", S12)
tf("fs-10", T, "A Fourier sine series always gives 0 at $x=0$ and $x=\\pm p$.", True, "Every term $\\sin(n\\pi x/p)$ is 0 there. (Procedures sheet)", PS)
sa("fs-11", T, "Name the three half-range expansions of $f$ on $(0,L)$ and the extension each one uses.", "Cosine series (even extension), sine series (odd extension), full series (repeat with period $L$, so $p=L/2$).", "The half-range coefficient formulas are NOT on the sheet (derived from " + P2 + " by parity):\n$a_n=\\frac2L\\int_0^Lf\\cos\\frac{n\\pi x}L dx$\n$b_n=\\frac2L\\int_0^Lf\\sin\\frac{n\\pi x}L dx$", S12, ["cosine/even", "sine/odd", "full/period L"])
mcq("fs-12", T, "To evaluate a sum like $1-\\frac13+\\frac15-\\dots$ from a Fourier series, you:", ["Plug a convenient $x$ (0, $p/2$, $p$) into the series and use the convergence theorem for the left side", "Differentiate the series", "Integrate from 0 to $p$", "Set $n=1$"], 0, "Choose $x$ so the trig terms give a clean pattern ($1$, $(-1)^n$, or $1,0,-1,0$).\nAt a jump, the left side is the average value " + DEF + ".", PS)
tf("fs-13", T, "The complex Fourier series is $\\sum_{-\\infty}^\\infty c_ne^{in\\pi x/p}$ with $c_n=\\frac1{2p}\\int_{-p}^pf\\,e^{-in\\pi x/p}dx$.", True, "Complex form " + DEF + "\nIt's equivalent to the real form through Euler's formula.", S12)
mcq("fs-14", T, "For integer $n$, $\\sin n\\pi$ and $\\cos n\\pi$ equal:", ["$0$ and $(-1)^n$", "$(-1)^n$ and $0$", "$1$ and $0$", "$0$ and $1$"], 0, "This is the most common simplification when computing coefficients.\nAlso: $\\sin(2n\\pi+\\theta)=\\sin\\theta$ " + P2 + ".", PS)

T = "PDEs & separation of variables"
mcq("pd-01", T, "The 1-D heat equation is:", ["$k\\,u_{xx}=u_t$", "$a^2u_{xx}=u_{tt}$", "$u_{xx}+u_{yy}=0$", "$u_t+u_x=0$"], 0, "PDE forms " + DEF + "\nWave: $a^2u_{xx}=u_{tt}$. Laplace: $u_{xx}+u_{yy}=0$.", S13)
mcq("pd-02", T, "Classify by $B^2-4AC$: the heat, wave and Laplace equations are:", ["Parabolic, hyperbolic, elliptic", "Elliptic, parabolic, hyperbolic", "Hyperbolic, elliptic, parabolic", "All parabolic"], 0, "Classification " + DEF + ": $=0$ parabolic, $>0$ hyperbolic, $<0$ elliptic.\nHeat: $A=k$, $C=0$ → 0.\nWave: $A=a^2$, $C=-1$ → $4a^2>0$.\nLaplace: $A=C=1$ → $-4<0$.", S13)
sa("pd-03", T, "Describe separation of variables for a linear PDE.", "Assume $u=X(x)T(t)$ and substitute. Divide so each side depends on one variable, and set both sides equal to $-\\lambda$. Solve the ODEs, using the homogeneous BCs to find eigenvalues and eigenfunctions. Superpose the product solutions and fit the IC with a Fourier series.", "Check the three cases $\\lambda=0$, $\\lambda=-\\alpha^2$, $\\lambda=\\alpha^2$.\nThe IC fit uses the half-range formulas (derived from " + P2 + ").", S13, ["u = XT", "−λ", "eigenvalues", "superposition", "Fourier coefficients"])
tf("pd-04", T, "Superposition: if $u_1,\\dots,u_k$ solve a homogeneous linear PDE, so does any linear combination.", True, "That's why $\\sum A_nX_nT_n$ is still a solution.", S13)
mcq("pd-05", T, "For the heat equation with $u(0,t)=u(L,t)=0$, the eigenfunctions are:", ["$\\sin\\frac{n\\pi x}{L}$, $\\lambda_n=(n\\pi/L)^2$", "$\\cos\\frac{n\\pi x}{L}$", "$e^{n\\pi x/L}$", "$\\sinh\\frac{n\\pi x}{L}$"], 0, "(derived) $X''+\\lambda X=0$ with $X(0)=0$ gives $X=\\sin\\alpha x$.\n$X(L)=0$ gives $\\alpha L=n\\pi$.\nThe IC then becomes a half-range sine series.", S13)
mcq("pd-06", T, "Insulated ends ($u_x(0,t)=u_x(L,t)=0$) lead to:", ["A cosine series, including a constant from $\\lambda_0=0$", "A sine series", "Only the zero solution", "Exponential eigenfunctions"], 0, "Neumann BCs give $X=\\cos(n\\pi x/L)$, including $n=0$.\nAs $t\\to\\infty$, $u$ tends to the average of the initial temperature: no heat leaves the rod.", S13)
mcq("pd-07", T, "Which BC is a Neumann condition?", ["$\\partial u/\\partial x=0$ at $x=0$", "$u=0$ at $x=0$", "$u_x=-h(u-u_m)$ at $x=L$", "$u(x,0)=f(x)$"], 0, "BC types " + DEF + ":\nDirichlet specifies $u$\nNeumann specifies $\\partial u/\\partial n$\nRobin specifies a mix of the two (convection)", S13)
tf("pd-08", T, "For the heat equation, mode $n$ decays like $e^{-k(n\\pi/L)^2t}$, so higher modes die out faster.", True, "The exponent grows like $n^2$, so after a short time the first term dominates.", S13)
mcq("pd-09", T, "The wave equation needs how many initial conditions?", ["Two: $u(x,0)$ and $u_t(x,0)$", "One", "None", "Three"], 0, "It's second order in $t$.\nThe heat equation is first order in $t$, so it needs one IC.", S13)
sa("pd-10", T, "For a string with fixed ends, what are the standing waves and the fundamental frequency?", "Each $u_n=(A_n\\cos\\frac{n\\pi a}{L}t+B_n\\sin\\frac{n\\pi a}{L}t)\\sin\\frac{n\\pi x}{L}$ is a standing wave (normal mode). For $n=1$: $f_1=\\frac{a}{2L}$.", "(derived) The angular frequency is $n\\pi a/L$, so $f_n=\\dfrac{na}{2L}$.\nHigher modes are overtones. Points where $\\sin(n\\pi x/L)=0$ are nodes.", S13, ["standing waves", "f1 = a/2L", "nodes"])
mcq("pd-11", T, "Laplace's equation on a rectangle with three zero edges: the non-periodic direction uses:", ["$\\sinh$ or $\\cosh$", "$\\sin$ or $\\cos$", "decaying exponentials in $t$", "polynomials"], 0, "The direction with homogeneous BCs gets $\\sin$ (the eigenfunctions).\nThe other direction gets $\\sinh/\\cosh$ (hyperbolic identities " + P2 + ").", S13)
tf("pd-12", T, "If a rectangle has nonzero temperatures on two edges, split into two one-edge problems and add.", True, "Superposition for Laplace's equation.", S13)
sa("pd-13", T, "How do you handle nonhomogeneous time-independent BCs like $u(0,t)=u_0$, $u(L,t)=u_1$?", "Write $u=v(x,t)+\\psi(x)$. The steady state $\\psi$ satisfies $k\\psi''=0$ (plus any source term) and the nonhomogeneous BCs. Then $v$ satisfies the heat equation with homogeneous BCs and IC $v(x,0)=f-\\psi$. As $t\\to\\infty$, $u\\to\\psi$.", "Section 13.6.\nWith no source, $\\psi$ is the straight line between $u_0$ and $u_1$.", S13, ["u = v + ψ", "steady state", "homogeneous BCs for v"])
mcq("pd-14", T, "In the separated heat problem, the $T(t)$ equation is:", ["$T'+k\\lambda T=0$, so $T=e^{-k\\lambda t}$", "$T''+a^2\\lambda T=0$", "$T'=\\lambda T$ (growth)", "$T=$ constant"], 0, "From $\\dfrac{X''}{X}=\\dfrac{T'}{kT}=-\\lambda$.\nWith $\\lambda>0$, $T$ decays, as heat physically must.", S13)
